-- KSHANA collection: 1 collection + 26 watches. Safe to re-run (updates in place).
-- The 20 watches with an approved image are live. The 6 that are a draft or on hold (KS03, KS22 to KS26) are added HIDDEN:
--   switch them on later in Admin → Products (tick Active) once the image / decision is done.
alter table collections add column if not exists tagline_hi text, add column if not exists headline_hi text, add column if not exists description_hi text, add column if not exists story_hi text, add column if not exists meaning_hi text, add column if not exists show_glow boolean default true;
alter table products add column if not exists tags jsonb default '[]'::jsonb, add column if not exists hindi_line text, add column if not exists tagline_hi text, add column if not exists description_hi text, add column if not exists long_description_hi text, add column if not exists stock_mode text default 'in_stock';

insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,image,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active,show_glow)
values ('kshana','KSHANA','kshana',$q$An instant, kept.$q$,$q$Yuga is an age. Kshana is an instant.$q$,$q$Kshana is an instant: the smallest part of time. This line keeps the idea small and exact. A round case, a leather strap, a dial with nothing on it but twelve faceted batons and a thin seconds hand.$q$,'20 watches','क्षण',$q$Kshana · a single instant · the smallest part of time$q$,$q$Yuga is an age. Kshana is an instant. Between them sits everything a watch is for. KSHANA is the quiet end of that idea: no motif, no ornament, only the hour.$q$,'Black',6,$q$https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KSH-SL-BK-BS.png$q$,$q$एक क्षण, सहेजा हुआ।$q$,$q$युग एक काल है। क्षण एक पल।$q$,$q$क्षण एक पल है: समय का सबसे छोटा अंश। यह शृंखला विचार को छोटा और सटीक रखती है। गोलाकार आवरण, चर्म का पट्टा, और एक डायल जिस पर बारह पहलदार पट्टिकाओं और एक पतली सेकंड की सुई के सिवा कुछ नहीं।$q$,$q$क्षण · एक पल · समय का सबसे छोटा अंश$q$,$q$युग एक काल है। क्षण एक पल। इन दोनों के बीच वह सब है जिसके लिए घड़ी बनी है। क्षण उसी विचार का शांत छोर है: न कोई आकृति, न अलंकरण, केवल समय।$q$,true,true)
