-- KS01 Nisha (ready)
insert into products(slug,name,sku,tagline,description,long_description,case_color,strap_color,price,compare_price,stock,edition_total,edition_sold,featured,sort,seo_title,seo_description,tagline_hi,description_hi,long_description_hi,collection_id,features,specs,images,stock_mode,active,tags)
select $q$kshana-nisha$q$,$q$KSHANA Nisha$q$,$q$YG-KSH-SL-BK-BS$q$,$q$Quiet as the night.$q$,$q$A round 40 mm watch with a silver case on a black leather strap, and a black dial with silver hands.$q$,$q$Silver light on black. Nisha is the night kept simple, a watch that asks for nothing and is always ready.

Twelve faceted batons catch the light, with a double baton at twelve. The dial carries no motif, only a thin seconds hand moving around it.

Silver is the cool of moonlight. The case is a silver finish, on a black leather strap with stitched edges.$q$,$q$Silver$q$,$q$Black$q$,1499,2999,50,0,0,false,101,$q$KSHANA Nisha | Silver Black Leather Watch | YUGASTRA$q$,$q$KSHANA Nisha: round 40 mm watch. Silver case, black leather strap, black dial with silver hands. 1-year warranty. ₹1,499.$q$,$q$रात्रि जितनी शांत।$q$,$q$गोलाकार 40 मिमी की घड़ी: रजत आवरण, श्याम चर्म का पट्टा, और श्याम डायल पर रजत सुइयाँ।$q$,$q$रजत प्रकाश, श्याम पर। निशा सरलता में रखी रात्रि है, एक ऐसी घड़ी जो कुछ नहीं माँगती और सदा तैयार रहती है।

बारह पहलदार पट्टिकाएँ प्रकाश को थामती हैं, बारह पर एक दोहरी पट्टिका के साथ। डायल पर कोई आकृति नहीं है, केवल एक पतली सेकंड की सुई उसके चारों ओर घूमती है।

रजत चंद्र-प्रकाश की शीतलता है। आवरण रजत सतह का है, और साथ में श्याम चर्म का पट्टा है, जिसके किनारों पर सिलाई है।$q$,c.id,$q$["Round 40 mm case, silver finish", "22 mm black leather strap, stitched edges", "Black dial, silver hands", "12 faceted batons, double baton at twelve", "Japanese quartz movement", "1-year warranty"]$q$::jsonb,$q${"Collection": "KSHANA", "Movement": "Japanese quartz", "Case": "Round, 40 mm, silver finish", "Strap": "Black leather, 22 mm", "Dial": "Black dial, silver hands", "Markers": "Twelve faceted batons, double at 12", "Hands": "Three, thin seconds hand", "Warranty": "1 year"}$q$::jsonb,$q$["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KSH-SL-BK-BS.png"]$q$::jsonb,'in_stock',true,'[]'::jsonb from collections c where c.slug='kshana'
